sys_script_include.script:
function AppBuilderDefineUiSection(vUiSection, aElements)
{
	var grUiSection = GetRecord('sys_ui_section',vUiSection);
	if (IsValidRecord(grUiSection) == false)
	{
		return false;
	}
	aElements = GetArrayValue(aElements);
	if (aElements.length == 0)
	{
		return false;
	}

	var bSuccess = true;

	for (var nElement = 0; nElement < aElements.length; nElement++)
	{
		var vElement = aElements[nElement];

		var strElement = '';
		var strType = '';
		var strSysUiFormatterSysId = '';
		if (IsObject(vElement) == false)
		{
			strElement = GetStringValue(vElement);
		}
		else
		{
			strElement = GetStringValue(GetValue(vElement,'element'));
			strType = GetStringValue(GetValue(vElement,'type'));
			strSysUiFormatterSysId = GetStringValue(GetValue(vElement,'sys_ui_formatter'));
		}

		if (   strElement == '.begin_split'
			|| strElement == '.split'
			|| strElement == '.end_split')
		{
			strType = strElement;
		}

		if (strElement == 'activity.xml')
		{
			strType = 'formatter';
			strSysUiFormatterSysId = AppGetProperty('ui_element.formatter.activity.default');
		}

		if (IsValidSysId(strElement))
		{
			strType = 'annotation';
		}


		var grUiElement = new GlideRecord('sys_ui_element');
		grUiElement.initialize();
		grUiElement.sys_ui_section = grUiSection.sys_id;
		grUiElement.position = nElement;
		grUiElement.element = strElement;
		grUiElement.type = strType;
		grUiElement.sys_ui_formatter = strSysUiFormatterSysId;
		var strUiElementSysId = GlideRecordInsert(grUiElement);
		if (IsValidSysId(strUiElementSysId) == false)
		{
			bSuccess = false;
		}
	}
	return bSuccess;
}
